// An example message for every tile of this view, written by andon out.
// msg.topic is the tile ID. Below each tile, every form it takes: the first
// one is sent, the others are commented out. Replace the values with your own.

// t_label_1 - label - Label
//   a text or a number (replaces the value)
node.send({ topic: "t_label_1", payload: "Text" });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_label_1", payload: {"status":"warning"} });

// t_label_2 - label - Label number
//   a text or a number (replaces the value)
node.send({ topic: "t_label_2", payload: 42 });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_label_2", payload: {"status":"warning"} });

// t_gauge_3 - gauge - Gauge
//   a number (replaces the value)
node.send({ topic: "t_gauge_3", payload: 62 });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_gauge_3", payload: {"status":"warning"} });

// t_progress_4 - progress - Progress
//   a number (replaces the value)
node.send({ topic: "t_progress_4", payload: 30 });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_progress_4", payload: {"status":"warning"} });

// t_line_5 - line - Line
//   a number (is appended to the series, at the time it arrives)
node.send({ topic: "t_line_5", payload: 14 });
//   a number with msg.timestamp (is appended at that time, in milliseconds or ISO 8601)
// node.send({ topic: "t_line_5", payload: 14, timestamp: Date.now() });
//   a number with msg.series (is appended to the series of that name)
// node.send({ topic: "t_line_5", payload: 10, series: "Series B" });
//   an array of [timestamp, value] pairs (replaces the series; msg.series picks which)
// node.send({ topic: "t_line_5", payload: [[new Date(Date.now() - 180000).toISOString(), 10], [new Date(Date.now() - 120000).toISOString(), 12], [new Date(Date.now() - 60000).toISOString(), 11], [new Date().toISOString(), 14]] });
//   an object {series: [{name, samples}]} (replaces every series)
// node.send({ topic: "t_line_5", payload: { series: [{ name: "Series A", samples: [[new Date(Date.now() - 180000).toISOString(), 10], [new Date(Date.now() - 120000).toISOString(), 12], [new Date(Date.now() - 60000).toISOString(), 11], [new Date().toISOString(), 14]] }, { name: "Series B", samples: [[new Date(Date.now() - 180000).toISOString(), 8], [new Date(Date.now() - 120000).toISOString(), 9], [new Date(Date.now() - 60000).toISOString(), 9.5], [new Date().toISOString(), 10]] }] } });
//   an object {series: [{name, start, stepSec, points}]} (replaces every series: a point every stepSec from start, in UTC)
// node.send({ topic: "t_line_5", payload: { series: [{ name: "Series A", start: new Date(Date.now() - 10800000).toISOString(), stepSec: 3600, points: [10,12,11,14] }, { name: "Series B", start: new Date(Date.now() - 10800000).toISOString(), stepSec: 3600, points: [8,9,9.5,10] }] } });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_line_5", payload: {"status":"warning"} });

// t_line_6 - line - Line steps
//   an array of [timestamp, value] pairs (replaces the series; msg.series picks which)
node.send({ topic: "t_line_6", payload: [[new Date(Date.now() - 180000).toISOString(), 3], [new Date(Date.now() - 120000).toISOString(), 4], [new Date(Date.now() - 60000).toISOString(), 6], [new Date().toISOString(), 5]] });
//   an object {series: [{name, samples}]} (replaces every series)
// node.send({ topic: "t_line_6", payload: { series: [{ name: "Series A", samples: [[new Date(Date.now() - 180000).toISOString(), 3], [new Date(Date.now() - 120000).toISOString(), 4], [new Date(Date.now() - 60000).toISOString(), 6], [new Date().toISOString(), 5]] }] } });
//   an object {series: [{name, start, stepSec, points}]} (replaces every series: a point every stepSec from start, in UTC)
// node.send({ topic: "t_line_6", payload: { series: [{ name: "Series A", start: new Date(Date.now() - 10800000).toISOString(), stepSec: 3600, points: [3,4,6,5] }] } });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_line_6", payload: {"status":"warning"} });

// t_bar_7 - bar - Bar over time
//   an array of [timestamp, value] pairs (replaces the series; msg.series picks which)
node.send({ topic: "t_bar_7", payload: [[new Date(Date.now() - 180000).toISOString(), 7], [new Date(Date.now() - 120000).toISOString(), 9], [new Date(Date.now() - 60000).toISOString(), 6], [new Date().toISOString(), 8]] });
//   an object {series: [{name, samples}]} (replaces every series)
// node.send({ topic: "t_bar_7", payload: { series: [{ name: "Series A", samples: [[new Date(Date.now() - 180000).toISOString(), 7], [new Date(Date.now() - 120000).toISOString(), 9], [new Date(Date.now() - 60000).toISOString(), 6], [new Date().toISOString(), 8]] }, { name: "Series B", samples: [[new Date(Date.now() - 180000).toISOString(), 8], [new Date(Date.now() - 120000).toISOString(), 8], [new Date(Date.now() - 60000).toISOString(), 8], [new Date().toISOString(), 8]] }] } });
//   an object {series: [{name, start, stepSec, points}]} (replaces every series: a point every stepSec from start, in UTC)
// node.send({ topic: "t_bar_7", payload: { series: [{ name: "Series A", start: new Date(Date.now() - 10800000).toISOString(), stepSec: 3600, points: [7,9,6,8] }, { name: "Series B", start: new Date(Date.now() - 10800000).toISOString(), stepSec: 3600, points: [8,8,8,8] }] } });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_bar_7", payload: {"status":"warning"} });

// t_bar_8 - bar - Bar
//   an array of numbers, one per category (replaces the values; categories: 3)
node.send({ topic: "t_bar_8", payload: [4,7,2] });
//   an object {categories, series} (replaces the categories and their values together)
// node.send({ topic: "t_bar_8", payload: {"categories":["A","B","C"],"series":[{"name":"Series A","values":[4,7,2]}]} });
//   an object {series: [{name, values, statuses}]} (a verdict per bar: ok, warning, critical or null)
// node.send({ topic: "t_bar_8", payload: {"series":[{"name":"Series A","values":[4,7,2],"statuses":[null,null,"critical"]}]} });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_bar_8", payload: {"status":"warning"} });

// t_bar_9 - bar - Bar two series
//   an array of numbers, one per category (replaces the values; categories: 3)
node.send({ topic: "t_bar_9", payload: [4,7,2] });
//   an array of numbers with msg.series (replaces the values of the series of that name)
// node.send({ topic: "t_bar_9", payload: [5,5,5], series: "Series B" });
//   an object {categories, series} (replaces the categories and their values together)
// node.send({ topic: "t_bar_9", payload: {"categories":["A","B","C"],"series":[{"name":"Series A","values":[4,7,2]},{"name":"Series B","values":[5,5,5]}]} });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_bar_9", payload: {"status":"warning"} });

// t_pie_10 - pie - Pie
//   an array of numbers, one per category (replaces the values; categories: 3)
node.send({ topic: "t_pie_10", payload: [50,30,20] });
//   an object {categories, series} (replaces the categories and their values together)
// node.send({ topic: "t_pie_10", payload: {"categories":["A","B","C"],"series":[{"name":"Series A","values":[50,30,20]}]} });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_pie_10", payload: {"status":"warning"} });

// t_donut_11 - donut - Donut
//   a number (replaces the value)
node.send({ topic: "t_donut_11", payload: 100 });
//   an array of numbers, one per category (replaces the values; categories: 3)
// node.send({ topic: "t_donut_11", payload: [50,30,20] });
//   an object {categories, series} (replaces the categories and their values together)
// node.send({ topic: "t_donut_11", payload: {"categories":["A","B","C"],"series":[{"name":"Series A","values":[50,30,20]}]} });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_donut_11", payload: {"status":"warning"} });

// t_table_12 - table - Table
//   an array of rows, each an array of cells (replaces the rows; columns: 3)
node.send({ topic: "t_table_12", payload: [["Row 1","on",1.5]] });
//   an array of {cells, status} (replaces the rows, with a status per row)
// node.send({ topic: "t_table_12", payload: [{"cells":["Row 1","on",1.5],"status":"warning"}] });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_table_12", payload: {"status":"warning"} });

// t_timeline_13 - timeline - Timeline
//   a state ID (on, idle, off) (starts a new segment, at the time it arrives)
node.send({ topic: "t_timeline_13", payload: "on" });
//   a state ID with msg.timestamp (starts the segment at that time)
// node.send({ topic: "t_timeline_13", payload: "on", timestamp: Date.now() });
//   a state ID with msg.lane (starts a segment in the lane of that name)
// node.send({ topic: "t_timeline_13", payload: "on", lane: "Lane B" });
//   an object {from, to} (moves the time axis; what lies before from is trimmed)
// node.send({ topic: "t_timeline_13", payload: { from: new Date(Date.now() - 28800000).toISOString(), to: new Date().toISOString() } });
//   an object of fields, e.g. {"status": "warning"} (sets them; null removes one)
// node.send({ topic: "t_timeline_13", payload: {"status":"warning"} });

// The same values as one message: without msg.topic, msg.payload is an object
// of tile IDs and values, for a source that has them all at once. The message
// is taken or refused as a whole, and msg.series, msg.lane and msg.timestamp
// would apply to every tile in it. To use it, comment out the node.send lines
// above and remove the // in front of the lines below.
// A whole view document as msg.payload (with id, schemaVersion, name and tiles)
// replaces the template instead: for a source that builds its tiles itself.
//
// return { payload: {
//     "t_label_1": "Text",
//     "t_label_2": 42,
//     "t_gauge_3": 62,
//     "t_progress_4": 30,
//     "t_line_5": 14,
//     "t_line_6": [[new Date(Date.now() - 180000).toISOString(), 3], [new Date(Date.now() - 120000).toISOString(), 4], [new Date(Date.now() - 60000).toISOString(), 6], [new Date().toISOString(), 5]],
//     "t_bar_7": [[new Date(Date.now() - 180000).toISOString(), 7], [new Date(Date.now() - 120000).toISOString(), 9], [new Date(Date.now() - 60000).toISOString(), 6], [new Date().toISOString(), 8]],
//     "t_bar_8": [4,7,2],
//     "t_bar_9": [4,7,2],
//     "t_pie_10": [50,30,20],
//     "t_donut_11": 100,
//     "t_table_12": [["Row 1","on",1.5]],
//     "t_timeline_13": "on"
// } };

return null;

